import re

def parse(lines):
    skip = []
    summ = {'name': 'summary', 'kind': 'kv', 'lines': [], 'records': [{}]}
    tabs = {'name': 'tables', 'kind': 'table', 'lines': [], 'records': []}
    peers = {'name': 'peers', 'kind': 'table', 'lines': [], 'records': []}
    ribs = {'name': 'peer_ribs', 'kind': 'table', 'lines': [], 'records': []}
    peer_re = re.compile(r'^(?P<peer>[0-9A-Fa-f:.]+)\s+(?P<as>\d+)\s+(?P<inpkt>\d+)\s+(?P<outpkt>\d+)\s+(?P<outq>\d+)\s+(?P<flaps>\d+)\s+(?P<last>\S(?:.*?\S)?)\s+(?P<state>\S+)$')
    rib_re = re.compile(r'^\s+(?P<table>\S+):\s+(?P<a>\d+)/(?P<r>\d+)/(?P<c>\d+)/(?P<d>\d+)\s*$')
    nums_re = re.compile(r'^\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s+(\d+)\s*$')
    kv_re = re.compile(r'(Groups|Peers|Down peers):\s*(\d+)')
    mode = None
    cur_table = None
    cur_peer = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.match(r'^\{\w+.*\}$', s) or re.match(r'^\S+@\S+[>#]', s):
            skip.append(i)
            continue
        if s.startswith('Table') and 'Tot Paths' in s:
            mode = 'tab'
            skip.append(i)
            continue
        if s.startswith('Peer') and 'InPkt' in s:
            mode = 'peer'
            skip.append(i)
            continue
        if mode is None:
            if s.startswith('Groups:'):
                for k, v in kv_re.findall(s):
                    summ['records'][0][k] = int(v)
                summ['lines'].append(i)
                continue
            m = re.match(r'^([^:]+):\s*(.*)$', s)
            if m:
                summ['records'][0][m.group(1)] = m.group(2)
                summ['lines'].append(i)
            continue
        if mode == 'tab':
            m = nums_re.match(l)
            if m and cur_table is not None:
                g = m.groups()
                tabs['records'].append({'Table': cur_table, 'Tot Paths': int(g[0]), 'Act Paths': int(g[1]), 'Suppressed': int(g[2]), 'History': int(g[3]), 'Damp State': int(g[4]), 'Pending': int(g[5])})
                tabs['lines'].append(i)
                cur_table = None
                continue
            if re.match(r'^\S+$', l):
                cur_table = s
                tabs['lines'].append(i)
                continue
            continue
        if mode == 'peer':
            m = rib_re.match(l)
            if m and cur_peer is not None:
                ribs['records'].append({'Peer': cur_peer, 'Table': m.group('table'), 'Active': int(m.group('a')), 'Received': int(m.group('r')), 'Accepted': int(m.group('c')), 'Damped': int(m.group('d'))})
                ribs['lines'].append(i)
                continue
            m = peer_re.match(l)
            if m:
                cur_peer = m.group('peer')
                peers['records'].append({'Peer': cur_peer, 'AS': int(m.group('as')), 'InPkt': int(m.group('inpkt')), 'OutPkt': int(m.group('outpkt')), 'OutQ': int(m.group('outq')), 'Flaps': int(m.group('flaps')), 'Last Up/Dwn': m.group('last'), 'State': m.group('state')})
                peers['lines'].append(i)
    blocks = [b for b in (summ, tabs, peers, ribs) if b['lines']]
    return {'blocks': blocks, 'skip': skip}
